public abstract class Builder<T> where T : Builder<T>
{
    public string? Name { get; private set; }
    protected T Self => (T)this;                  // runtime-checked conversion
    public T Named(string name) { Name = name; return Self; }
}

public sealed class UserBuilder : Builder<UserBuilder>
{
    public UserBuilder WithEmail(string email) => this;
}

public interface IDescribable<T> where T : IDescribable<T>
{
    static abstract string TypeName { get; }
    static virtual string Describe() => T.TypeName;   // shared default
}

public static string Describe<T>() where T : IDescribable<T> => T.Describe();

